### Hallgato.java

```java
import java.util.Map;

public class Hallgato implements Comparable<Hallgato> {
    private String keresztNev;
    private String csaladNev;
    private String neptun;
    private Map<String, Integer> teljesitesek;

    public Hallgato(String keresztNev, String csaladNev, String neptun, Map<String, Integer> teljesitesek) {
        this.keresztNev = keresztNev;
        this.csaladNev = csaladNev;
        this.neptun = neptun;
        this.teljesitesek = teljesitesek;
    }

    @Override
    public String toString() {
        return "Hallgato{" +
                "keresztNev='" + keresztNev + '\'' +
                ", csaladNev='" + csaladNev + '\'' +
                ", neptun='" + neptun + '\'' +
                ", teljesitesek=" + teljesitesek +
                '}';
    }

    public Map<String, Integer> getTeljesitesek() {
        return teljesitesek;
    }

    // Kiegészítés: legjobb osztályzatot visszaadó paraméter nélküli, int-et visszaadó metódus:
    public int legjobbOsztalyzat() {
        if (teljesitesek == null || teljesitesek.isEmpty()) return 0;  // 0 ha semmi sincs
        int max = Integer.MIN_VALUE;
        for (Integer jegy : teljesitesek.values()) {
            if (jegy != null && jegy > max) max = jegy;
        }
        return max;
    }

    @Override
    public int compareTo(Hallgato o) {
        // Legjobb jegy szerint csökkenő sorrend
        int cmp = Integer.compare(o.legjobbOsztalyzat(), this.legjobbOsztalyzat());
        if (cmp != 0) return cmp;
        // Ha azonos, akkor neptun kód szerint növekvő
        return this.neptun.compareTo(o.neptun);
    }
}
```

