### Zh4.java

```java
import java.util.*;

public class Zh4 {
    public static Collection<Hallgato> rendez(Hallgato[] hallgatok) {
        List<Hallgato> eredmeny = new ArrayList<>();
        if (hallgatok == null || hallgatok.length == 0) return eredmeny;
        for (Hallgato h : hallgatok) {
            if (h != null)
                eredmeny.add(h);
        }
        Collections.sort(eredmeny); // Comparable implementáció szerint
        return eredmeny;
    }

    public static void teljesitesNelkuliekTorlese(List<Hallgato> hallgatok) {
        if (hallgatok == null) return;
        // Iteratorral biztonságos törletni
        Iterator<Hallgato> it = hallgatok.iterator();
        while (it.hasNext()) {
            Hallgato h = it.next();
            if (h == null || h.getTeljesitesek() == null || h.getTeljesitesek().isEmpty()) {
                it.remove();
            }
        }
    }

    public static void main(String[] args) {
        Hallgato hallgato1 = new Hallgato("Bela", "Kiss", "NGRSPJ", new HashMap<String, Integer>(){{put("Kalkulus",5); put("Diszkret matek",4); put("Programozas alapjai",3);}});
        Hallgato hallgato2 = new Hallgato("Bela", "Abraham", "XGRSPJ", new HashMap<String, Integer>(){{put("Kalkulus",4); put("Diszkret matek",4); put("Programozas alapjai",4);}});
        Hallgato hallgato3 = new Hallgato("Inez", "Mikola", "JRRAGS", new HashMap<String, Integer>(){{put("Algoritmusok",5); put("Diszkret matek",4);}});
        Hallgato hallgato4 = new Hallgato("Eszter", "Nemet", "PPPZZZ", new HashMap<String, Integer>());

        Hallgato[] hallgatok = new Hallgato[]{hallgato1, hallgato2, hallgato3, hallgato4};
        System.out.println("\nRendezve:");
        for (Hallgato h : rendez(hallgatok)) {
            System.out.println(h + "  (legjobb: " + h.legjobbOsztalyzat() + ")");
        }

        System.out.println("\nTeljesites nelkuli torles elott: ");
        List<Hallgato> tesztList = new ArrayList<>(Arrays.asList(hallgatok));
        for (Hallgato h : tesztList)
            System.out.println(h);
        teljesitesNelkuliekTorlese(tesztList);
        System.out.println("Teljesites nelkuli torles utan:");
        for (Hallgato h : tesztList)
            System.out.println(h);
    }
}
```

