Certainly! You can sort an array of numbers in **descending order** using the JavaScript `Array.prototype.sort()` method with a custom compare function.

Here’s how you can do it:

```javascript
const numbers = [34, 7, 23, 32, 5, 62];

numbers.sort(function(a, b) {
  return b - a; // For descending order
});

console.log(numbers); // Output: [62, 34, 32, 23, 7, 5]
```

**Explanation:**
- The `sort()` method sorts the array **in place**.
- The compare function `(a, b) => b - a` ensures that higher values come first (descending order).

---

**If you want a reusable function:**

```javascript
function sortDescending(arr) {
  return arr.slice().sort((a, b) => b - a);
}

const numbers = [34, 7, 23, 32, 5, 62];
const sorted = sortDescending(numbers);

console.log(sorted); // Output: [62, 34, 32, 23, 7, 5]
```

*The above function returns a **new sorted array** without modifying the original one.*

Certainly! Below is a comprehensive example in PHP to:

- Connect to a MySQL database using **PDO**.
- Create two tables: `users` and `orders` with the required columns and a foreign key relationship.
- Include **data validation** when inserting data into these tables.
- Handle errors properly using try-catch blocks.
- Prepare and execute INSERT queries using prepared statements to prevent SQL injection.

---

```php
<?php
// Database configuration
$host = 'localhost';
$db   = 'your_database';    // Replace with your database
$user = 'your_username';    // Replace with your username
$pass = 'your_password';    // Replace with your password
$charset = 'utf8mb4';

// Setup DSN
$dsn = "mysql:host=$host;dbname=$db;charset=$charset";

// Options for PDO
$options = [
    PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, // Use exceptions for error handling
    PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
    PDO::ATTR_EMULATE_PREPARES => false,
];

try {
    // Create PDO instance
    $pdo = new PDO($dsn, $user, $pass, $options);

    // -----------------------------------------------
    // CREATE TABLES
    // -----------------------------------------------
    $createUsersTable = "
    CREATE TABLE IF NOT EXISTS users (
        user_id INT AUTO_INCREMENT PRIMARY KEY,
        username VARCHAR(50) NOT NULL UNIQUE,
        password VARCHAR(255) NOT NULL,
        contact_info VARCHAR(100)
    ) ENGINE=InnoDB;
    ";

    $createOrdersTable = "
    CREATE TABLE IF NOT EXISTS orders (
        order_id INT AUTO_INCREMENT PRIMARY KEY,
        user_id INT NOT NULL,
        product_name VARCHAR(100) NOT NULL,
        quantity INT NOT NULL,
        total_cost DECIMAL(10,2) NOT NULL,
        FOREIGN KEY (user_id) REFERENCES users(user_id) ON DELETE CASCADE
    ) ENGINE=InnoDB;
    ";

    $pdo->exec($createUsersTable);
    $pdo->exec($createOrdersTable);

    // -----------------------------------------------------
    // VALIDATION FUNCTIONS
    // -----------------------------------------------------
    function validateUser($username, $password, $contactInfo) {
        if (empty($username) || strlen($username) < 3) return "Username must be at least 3 characters.";
        if (empty($password) || strlen($password) < 6) return "Password must be at least 6 characters.";
        if (!empty($contactInfo) && !filter_var($contactInfo, FILTER_VALIDATE_EMAIL)) {
            return "Contact information must be a valid email address.";
        }
        return true;
    }
    function validateOrder($userId, $productName, $quantity, $totalCost) {
        if (empty($userId) || !is_numeric($userId) || $userId <= 0) return "Invalid User ID.";
        if (empty($productName) || strlen($productName) < 2) return "Product name too short.";
        if (!is_numeric($quantity) || $quantity <= 0) return "Quantity must be a positive integer.";
        if (!is_numeric($totalCost) || $totalCost < 0) return "Total cost must be non-negative.";
        return true;
    }

    // -----------------------------------------------------
    // INSERT USER
    // -----------------------------------------------------
    function insertUser($pdo, $username, $password, $contactInfo) {
        // Validate input
        $validation = validateUser($username, $password, $contactInfo);
        if ($validation !== true) {
            throw new Exception("User validation failed: $validation");
        }

        // Hash password
        $hash = password_hash($password, PASSWORD_DEFAULT);

        // Attempt to insert user
        $stmt = $pdo->prepare("INSERT INTO users (username, password, contact_info) VALUES (?, ?, ?)");
        $stmt->execute([$username, $hash, $contactInfo]);

        // Return new user's ID
        return $pdo->lastInsertId();
    }

    // -----------------------------------------------------
    // INSERT ORDER
    // -----------------------------------------------------
    function insertOrder($pdo, $userId, $productName, $quantity, $totalCost) {
        // Validate input
        $validation = validateOrder($userId, $productName, $quantity, $totalCost);
        if ($validation !== true) {
            throw new Exception("Order validation failed: $validation");
        }

        // Check userId exists
        $stmt = $pdo->prepare("SELECT user_id FROM users WHERE user_id=?");
        $stmt->execute([$userId]);
        if ($stmt->fetch() === false) {
            throw new Exception("User with ID $userId not found.");
        }

        // Insert order
        $stmt = $pdo->prepare("INSERT INTO orders (user_id, product_name, quantity, total_cost) VALUES (?, ?, ?, ?)");
        $stmt->execute([$userId, $productName, $quantity, $totalCost]);
        return $pdo->lastInsertId();
    }

    // -----------------------------------------------------
    // EXAMPLES OF USAGE (WITH ERROR HANDLING)
    // -----------------------------------------------------
    try {
        $newUserId = insertUser($pdo, 'john_doe', 'secret123', 'john.doe@example.com');
        echo "User created with ID: $newUserId" . PHP_EOL;

        $newOrderId = insertOrder($pdo, $newUserId, 'Laptop', 2, 1999.98);
        echo "Order created with ID: $newOrderId" . PHP_EOL;
    } catch (Exception $e) {
        echo "Error: {$e->getMessage()}" . PHP_EOL;
    }

} catch (PDOException $e) {
    // Handle DB connection or creation errors
    echo "Database error: {$e->getMessage()}" . PHP_EOL;
}
?>
```

---

### Notes:

- **Modify** `$db`, `$user`, and `$pass` at the top for your environment.
- The code includes **CREATE TABLE** statements; they will only be executed once.
- **Validation** for username, password, email, and order details is included. Extend these as needed.
- All data insertions are **prepared statements with error handling**.
- Sample insertions and error catching are shown at the end.
- **Password** is securely hashed before database storage.
- **Contact info** is validated as an email. You can adapt this if you want other types of contact info.

