4. **Flexible interfaces** for user convenience.

## Implementation

```python
import math

class Geometry3DError(Exception):
    """Custom exception for Geometry3D."""
    pass


class Geometry3D:
    """Class for computing and verifying properties of 3D geometric shapes."""
    _SHAPES = {
        "cube": ["side"],
        "cuboid": ["length", "width", "height"],
        "sphere": ["radius"],
        "cylinder": ["radius", "height"],
        "pyramid": ["base_length", "base_width", "height"]
    }

    def __init__(self):
        pass

    # ---- Input validation helpers ----
    @staticmethod
    def _check_positive(**kwargs):
        for k, v in kwargs.items():
            if not (isinstance(v, (int, float)) and v > 0):
                raise Geometry3DError(f"Parameter '{k}' must be a positive number. Got: {v}")

    @staticmethod
    def _check_args(params, required):
        if len(params) != len(required):
            raise Geometry3DError(f"Expected arguments {required}, got {list(params.keys())}")

    # ---- Volume computation methods ----
    @classmethod
    def volume_cube(cls, side):
        cls._check_positive(side=side)
        return side ** 3

    @classmethod
    def volume_cuboid(cls, length, width, height):
        cls._check_positive(length=length, width=width, height=height)
        return length * width * height

    @classmethod
    def volume_sphere(cls, radius):
        cls._check_positive(radius=radius)
        return (4/3) * math.pi * (radius ** 3)

    @classmethod
    def volume_cylinder(cls, radius, height):
        cls._check_positive(radius=radius, height=height)
        return math.pi * (radius ** 2) * height

    @classmethod
    def volume_pyramid(cls, base_length, base_width, height):
        cls._check_positive(base_length=base_length, base_width=base_width, height=height)
        return (base_length * base_width * height) / 3

    # ---- Dynamic volume calculation ----
    @classmethod
    def volume(cls, shape, **kwargs):
        shape = shape.lower()
        if shape not in cls._SHAPES:
            raise Geometry3DError(f"Unknown shape '{shape}'. Allowed: {list(cls._SHAPES.keys())}")
        required = cls._SHAPES[shape]
        cls._check_args(kwargs, required)
        method = getattr(cls, f"volume_{shape}")
        return method(**kwargs)

    # ---- Shape verification ----
    @classmethod
    def which_shape(cls, **kwargs):
        # Match by argument names and values
        candidates = []
        for shape, params in cls._SHAPES.items():
            if set(params) == set(kwargs.keys()):
                try:
                    # Try to compute to verify param value validity
                    method = getattr(cls, f"volume_{shape}")
                    v = method(**kwargs)
                    if v > 0:
                        candidates.append(shape)
                except Geometry3DError:
                    continue
        if not candidates:
            raise Geometry3DError("Could not identify a unique or valid 3D shape with given parameters.")
        if len(candidates) == 1:
            return candidates[0]
        else:
            # Ambiguous case, e.g. (side, side, side) could fit both cube & cuboid (if keys fit)
            return candidates

    # ---- Robust interface for argument checking ----
    @classmethod
    def volume_auto(cls, **kwargs):
        """Compute volume automatically inferring the shape if possible."""
        shape = cls.which_shape(**kwargs)
        # If ambiguous, raise error
        if isinstance(shape, list):
            raise Geometry3DError(f"Ambiguous parameters: matches {shape}. Provide with shape name for clarity.")
        return cls.volume(shape, **kwargs)
```

