Here's a robust function for **converting a nested JSON object into a nested HTML table**, with the following features:

- **Handles undefined fields** – displays them as `<i>undefined</i>`.
- **Handles unexpected data types** (functions, Symbols, etc.) gracefully.
- **Handles cyclic structures** using a WeakSet to avoid infinite loops.
- **Sorting option** at any level via a property path (like `"person.pets.age"`).
- Human-readable output (string, ready for DOM use or display).

---

```javascript
/**
 * Converts a nested JSON object into an HTML table.
 * Handles cycles, undefined, unexpected types, and sorting.
 * 
 * @param {Object|Array} obj - The input JSON object/array
 * @param {Object} options - Optional parameters
 *   options.sortBy: string | Array<string> - property path(s) to sort arrays by
 *   options.showTypes: boolean - if true, will display types
 *   options.maxDepth: number - prevent rendering too deep
 * @returns {string} - HTML string of the rendered table
 *
 * Example:
 *   toTable(json, { sortBy: ['person.pets.age'] })
 */
function toTable(obj, options={}) {
  const sortByPaths = [].concat(options.sortBy || []);
  const showTypes = !!options.showTypes;
  const maxDepth = isFinite(options.maxDepth) ? options.maxDepth : 10;
  const cyc = new WeakSet();

  // Helper: Converts value to HTML fragment
  function valueToHTML(value, path, depth) {
    if (depth > maxDepth) {
      return `<span style="color:gray;"><i>(max depth reached)</i></span>`;
    }
    if (value === undefined) return `<i>undefined</i>`;
    if (value === null) return `<i>null</i>`;
    if (typeof value === 'function') return `<i>[Function]</i>`;
    if (typeof value === 'symbol') return `<i>[Symbol]</i>`;
    if (typeof value === 'number' || typeof value === 'boolean') return String(value);
    if (typeof value === 'string') return escapeHtml(value);

    if (typeof value === 'object') {
      if (cyc.has(value)) {
        return `<span style="color:red;"><i>[Cyclic]</i></span>`;
      }
      cyc.add(value);

      const sortKey = getSortKeyForPath(path);
      let html;
      if (Array.isArray(value)) {
        html = arrayToTable(value, path, depth+1, sortKey);
      } else {
        html = objectToTable(value, path, depth+1, sortKey);
      }
      cyc.delete(value);
      return html;
    }
    // For other types
    return `<i>[${typeof value}]</i>`;
  }

  // Helper: Returns the first sortKey that applies to this path
  function getSortKeyForPath(path) {
    // Each sortByPath is a path string: eg: "person.pets.age"
    // if path matches the array parent (first N segments), the property after that is the key
    for (const sortBy of sortByPaths) {
      const parts = sortBy.split('.');
      if (parts.length < 2) continue;
      const parentPath = parts.slice(0, -1).join('.');
      const key = parts[parts.length-1];
      if (path === parentPath) return key;
    }
    return null;
  }

  // Helper: Escapes HTML
  function escapeHtml(str) {
    return String(str)
      .replace(/&/g,"&amp;")
      .replace(/</g,"&lt;")
      .replace(/>/g,"&gt;")
      .replace(/"/g,"&quot;")
      .replace(/'/g,"&#039;");
  }

  // Render a table from an object
  function objectToTable(obj, path, depth, sortKey) {
    let rows = '';
    for (const key of Object.keys(obj)) {
      const val = obj[key];
      let rendered = valueToHTML(val, (path ? path + '.' : '') + key, depth);
      let typeStr = showTypes ? ` <span style="color: #bbb; font-size: 80%;">(${typeof val})</span>` : '';
      rows += `<tr><th>${escapeHtml(key)}</th><td>${rendered}${typeStr}</td></tr>`;
    }
    return `<table border="1" cellspacing="0" cellpadding="3" style="border-collapse:collapse; background:#f8f8f8;">${rows}</table>`;
  }

  // Render a table from an array (treat as list of rows)
  function arrayToTable(arr, path, depth, sortKey) {
    let array = arr.slice();
    if (sortKey) {
      // Only sort if elements are objects and sortKey in them
      // Here try to handle numeric & lexicographic
      array.sort((a, b) => {
        let av = a && typeof a === 'object' ? a[sortKey] : undefined;
        let bv = b && typeof b === 'object' ? b[sortKey] : undefined;
        if (Number(av).toString() === av || Number(bv).toString() === bv) {
          av = Number(av); bv = Number(bv);
          if (isNaN(av) && isNaN(bv)) return 0;
          if (isNaN(av)) return 1;
          if (isNaN(bv)) return -1;
        }
        if (av === undefined && bv !== undefined) return 1;
        if (av !== undefined && bv === undefined) return -1;
        if (av > bv) return 1;
        if (av < bv) return -1;
        return 0;
      });
    }
    let headerSet = new Set();
    // Find all keys for header
    for (const item of array) {
      if (item && typeof item === 'object' && !Array.isArray(item)) {
        Object.keys(item).forEach(k=>headerSet.add(k));
      }
    }
    let headers = Array.from(headerSet);
    let hasHeaders = headers.length > 0;
    let rows = '';
    if (hasHeaders) {
      rows += '<tr>' + headers.map(h=>`<th>${escapeHtml(h)}</th>`).join('') + '</tr>';
      for (const item of array) {
        if (item && typeof item === 'object' && !Array.isArray(item)) {
          rows += '<tr>' + headers.map(key=>`<td>${valueToHTML(item[key], (path ? path+'.' : '')+key, depth)}</td>`).join('') + '</tr>';
        } else {
          // primitive element
          rows += `<tr><td colspan="${headers.length}">${valueToHTML(item, path, depth)}</td></tr>`;
        }
      }
    } else {
      for (const item of array) {
        rows += `<tr><td>${valueToHTML(item, path, depth)}</td></tr>`;
      }
    }
    return `<table border="1" cellspacing="0" cellpadding="3" style="border-collapse:collapse; background:#eef;">${rows}</table>`;
  }

  // Kick off the rendering
  return valueToHTML(obj, '', 1);
}

// =====================
// USAGE EXAMPLES
// =====================
