let navigation = [];

function render() {
    document.getElementById('main').innerHTML = '';
    document.getElementById('sliders').innerHTML = '';
    let parent = null, list = data;
    for (let depth = 0; depth <= navigation.length; depth++) {
        let idx = navigation[depth];
        if (depth === navigation.length) {
            renderBlocks(list, depth);
        }
        if (idx !== undefined) {
            renderSlider(list, idx, depth);
            parent = list[idx];
            list = (parent && parent.subcategories) ? parent.subcategories : [];
