## **src/crawler.js** (Crawler Class)

```javascript
const puppeteer = require('puppeteer');
const { URL } = require('url');

class PriorityQueue {
    constructor() { this.data = [];}
    enqueue(element, priority) {
        this.data.push({element, priority});
        this.data.sort((a,b) => a.priority - b.priority); // Lower is higher prio
    }
    dequeue() { return this.data.shift()?.element; }
    isEmpty() { return this.data.length === 0; }
}

function isTrap(url, prevUrls) {
    try {
        let u = new URL(url);
        // Exclude calendar traps, endless replyTo, session ids, page params > 20, extremely long queries
        if (/calendar|sessionid|replyto|sort=/.test(u.search)) return true;
        if (/page=(\d{3,})/.test(u.search)) return true;
        // Already crawled this exact path 3+ times
        const pathCount = prevUrls.filter(seen => new URL(seen).pathname === u.pathname).length;
        if (pathCount >= 3) return true;
        // Max length for fragment/query trap protection
        if (u.search.length > 100) return true;
    } catch(e) {}
    return false;
}

function calcPriority(url, depth, keywords) {
    // Lower is higher priority
    let prio = depth;
    if (keywords && keywords.length) {
        const lowered = url.toLowerCase();
        if (keywords.some(k=> lower
ed.includes(k.toLowerCase()))) prio -= 2;
    }
    if (/news|about|blog/.test(url)) prio -= 1;
    return Math.max(prio, 0);
}

class Crawler {
    constructor(params, onPageCrawled) {
        this.startUrl = params.startUrl;
        this.maxDepth = +params.maxDepth || 3;
        this.keywords = params.keywords || [];
        this.onPageCrawled = onPageCrawled; // Callback
        this.shouldStop = false;
        this.uniqueUrls = new Set();
        this.prevUrls = [];
        this.browser = null;
        this.queue = new PriorityQueue();
        this.crawledData = [];
    }

    async start() {
        this.shouldStop = false;
        this.browser = await puppeteer.launch({headless:true});
        this.queue.enqueue({url:this.startUrl, depth:0}, 0);

        while (!this.queue.isEmpty() && !this.shouldStop) {
            const item = this.queue.dequeue();
            const {url, depth} = item;
            if (depth > this.maxDepth) continue;
            if (this.uniqueUrls.has(url)) continue;
            if (isTrap(url, this.prevUrls)) continue;
            this.uniqueUrls.add(url);
            this.prevUrls.push(url);

            try {
                const page = await this.browser.newPage();
                await page.goto(url, {waitUntil: 'networkidle2', timeout: 20000});
                await page.waitForTimeout(1500);
                const html = await page.content();
                // Get visible text only
                const text = await page.evaluate(() => document.body.innerText);
                const links = await page.evaluate(()=>[...document.links].map(a=>a.href));
                this.crawledData.push({url, text, html, depth, links, date: (new Date()).toISOString()});
                this.onPageCrawled({url, text, depth});
                await page.close();

                // Add unique links to queue
                for (let link of links) {
                    if (!link.startsWith('http') || this.uniqueUrls.has(link)) continue;
                    if (isTrap(link, this.prevUrls)) continue;
                    const prio = calcPriority(link, depth+1, this.keywords);
                    this.queue.enqueue({url:link, depth:depth+1}, prio);
                }

            } catch (e) {
                // Ignore errors, mark as crawled
                console.warn(`[CRAWLER] Failed ${url}:`, e.message);
            }
        }
        await this.browser.close();
    }

    async stop() {
        this.shouldStop = true;
        if (this.browser) await this.browser.close();
    }

    async clear() {
        this.uniqueUrls.clear();
        this.prevUrls = [];
        this.crawledData = [];
    }
}

module.exports = Crawler;
```

