    let nl = vec![
        NestedList::Int(1),
        NestedList::List(vec![
            NestedList::Int(2),
            NestedList::List(vec![NestedList::Int(3), NestedList::Int(4)]),
        ]),
        NestedList::Int(5),
    ];
    match advanced_median_error_detect(&nl) {
        Ok(Some(med)) => println!("Median: {}", med),
        Ok(None) => println!("List is empty"),
