use std::collections::HashMap;

/// Given a string, returns a map from each word to its length.
fn word_length(s: &str) -> HashMap<String, usize> {
    let mut result = HashMap::new();
    // Words are space-separated in the input string.
    for word in s.split_whitespace() {
        // Insert word and its length into the map.
