public class Converter
{
    public static string CustomBinaryToOctal(string y)
    {
        // Remove leading zeros
        while (y.Length > 1 && y[0] == '0')
        {
            y = y.Substring(1);
        }

        // Check for invalid input
        if (y.Length == 0)
            return "Error: Invalid binary string";
        for (int i = 0; i < y.Length; i++)
        {
