                return "Error: Invalid binary string";
        }

        // Pad with leading zeros to make the length a multiple of 3
        while (y.Length % 3 != 0)
        {
            y = "0" + y;
        }

        // Map dictionary for conversion
        string[] digits = { "0", "1", "2", "3", "4", "5", "6", "7" };

