fn advanced_evaluate_string(s: &str, t: &str) -> Option<String> {
    match t {
        // If operation is "split"
        "split" => {
            if s.contains(';') {
                // Split on ';' and collect into a vector of strings, then join for demo purposes
                // You may return the vector itself if you wish
                Some(
                    s.split(';')
                        .map(|x| x.to_string())
                        .collect::<Vec<_>>()
                        .join(", ")
                )
