                // Split on '::'
                Some(
                    s.split("::")
                        .map(|x| x.to_string())
                        .collect::<Vec<_>>()
                        .join(", ")
                )
            } else {
                None
            }
        }

        // If operation is "caps"
        "caps" => {
            // Enumerate over the characters, check for uppercase and even index
            let sum: i32 = s
                .chars()
                .enumerate()
                .filter(|(i, c)| c.is_uppercase() && i % 2 == 0)
                .map(|(_, c)| {
                    // Convert to lowercase, subtract 'a', mod 26
                    ((c.to_ascii_lowercase() as i32 - 'a' as i32) % 26)
                })
                .sum();
            Some(sum.to_string())
        }

        // If operation is "rev"
        "rev" => {
            // Collect chars into a vector, reverse, and collect back to string
            let reversed: String = s.chars().rev().collect();
            Some(reversed)
        }

        // For any other operation, return None
        _ => None,
    }
}

