        self.name = name
        self._grades: List[Grade] = []

    def add_grade(self, grade: Grade) -> None:
        self._grades.append(grade)

    def remove_grade(self, subject: str) -> None:
        self._grades = [g for g in self._grades if g.subject != subject]

    def get_grade(self, subject: str) -> Optional[Grade]:
        for grade in self._grades:
            if grade.subject == subject:
                return grade
        return None

    def average_percentage(self) -> float:
        if not self._grades:
            return 0.0
        return sum(g.percentage() for g in self._grades) / len(self._grades)

    def grades_summary(self) -> Dict[str, float]:
        return {g.subject: g.percentage() for g in self._grades}

    def __repr__(self):
        return f"Student(student_id={self.student_id!r}, name={self.name!r}, grades={self._grades!r})"


class StudentRegistry:
    def __init__(self):
        self._students: Dict[int, Student] = {}

    def add_student(self, student: Student) -> None:
        self._students[student.student_id] = student

    def remove_student(self, student_id: int) -> None:
        if student_id in self._students:
            del self._students[student_id]

    def get_student(self, student_id: int) -> Optional[Student]:
        return self._students.get(student_id)

    def all_students(self) -> List[Student]:
        return list(self._students.values())

    def top_students(self, n: int = 1) -> List[Student]:
        return sorted(self._students.values(), key=lambda s: s.average_percentage(), reverse=True)[:n]

    def subject_averages(self, subject: str) -> float:
        scores = [s.get_grade(subject).percentage()
                  for s in self._students.values()
                  if s.get_grade(subject)]
        return sum(scores) / len(scores) if scores else 0.0

    def __repr__(self):
        return f"StudentRegistry({self._students!r})"

# Example usage:
if __name__ == "__main__":
    registry = StudentRegistry()

    alice = Student(1, "Alice")
    bob = Student(2, "Bob")

    alice.add_grade(Grade("Math", 90))
    alice.add_grade(Grade("History", 80))
    bob.add_grade(Grade("Math", 85))
    bob.add_grade(Grade("History", 95))

    registry.add_student(alice)
    registry.add_student(bob)

    print(registry.all_students())
    print("Top Student(s):", registry.top_students(1))
    print("Math class average:", registry.subject_averages("Math"))
