```csharp
using System;
using System.Collections.Generic;
using System.Linq;

class Program
{
    static void Main()
    {
        string[] reference = new string[] { "hello", "world", "this", "is", "a" };
        // We use a list for accumulation, which we will build in order after input
        List<string> matchingInputs = new List<string>();
        List<string> nonMatchingInputs = new List<string>();

        Console.WriteLine("Enter strings (type END to finish):");
        while (true)
        {
            string input;
            try
            {
                input = Console.ReadLine();
                if (input == null)
                {
                    Console.WriteLine("Input was null. Ending input.");
                    break;
                }
                if (input.Trim().ToUpper() == "END")
                {
                    break;
                }
            }
            catch (IOException ex)
            {
                Console.WriteLine($"Input error: {ex.Message}");
                continue; // skip this input, do not stop loop
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Unexpected error: {ex.Message}");
                continue;
            }

            if (reference.Contains(input) && !matchingInputs.Contains(input))
            {
                matchingInputs.Add(input);
            }
            else if (!reference.Contains(input))
            {
                nonMatchingInputs.Add(input);
            }
            // Duplicate reference input: ignore
        }

        // Compose result in reference order, then non-matching in order received
        List<string> result = new List<string>();
        foreach (string refItem in reference)
        {
            if (matchingInputs.Contains(refItem))
            {
                result.Add(refItem);
            }
        }
        result.AddRange(nonMatchingInputs);

        Console.WriteLine("------");
        Console.WriteLine("Result:");
        foreach (string s in result)
        {
            Console.WriteLine(s);
        }
    }
}
