**PHP:**
```php
<?php
/**
 * @param string[] $strings
 * @return string|null
 */
function most_frequent(array $strings): ?string {
    if (count($strings) === 0) {
        return null;
    }

    // Count occurrences
    $counts = array_count_values($strings);
    $max_count = max($counts);

    // Return the first string with max count (honors first occurrence)
    foreach ($strings as $s) {
        if ($counts[$s] === $max_count) {
            return $s;
        }
    }
}
```

